algorithm.rustSketch:
fn grid_paths(rows: usize, columns: usize) -> usize {
    let mut dp = vec![1; columns];
    for _ in 1..rows {
        for column in 1..columns { dp[column] += dp[column - 1]; }
    }
    dp[columns - 1]
}

